mapper.select:
SELECT 
FROM t_user_daily_usage
WHERE user_id = #{userId}
  AND package_id = #{packageId}
  AND usage_date = #{usageDate}
LIMIT 1

mapper.update:
UPDATE t_user_daily_usage
SET chat_count_used = chat_count_used + 1,
    last_chat_time = NOW(),
    update_time = NOW()
WHERE user_id = #{userId}
  AND package_id = #{packageId}
  AND usage_date = #{usageDate}
